<script setup>
import {ref,reactive,computed,onMounted} from 'vue'
const props=defineProps({api:Function,context:Object})
const portal=props.context.portal,roles=props.context.roles,buyer=!portal&&roles.some(r=>['BUYER','CAT-MGR','superAdmin'].includes(r)),fin=portal?roles.some(r=>['ADMIN','FINANCE'].includes(r)):roles.some(r=>['FIN','superAdmin'].includes(r)),ship=portal&&roles.some(r=>['ADMIN','SHIP'].includes(r)),admin=!portal&&roles.some(r=>['SYS-ADMIN','superAdmin'].includes(r))
const tab=ref('orders'),rows=ref([]),total=ref(0),page=ref(1),search=ref(''),po=ref(null),asn=ref(null),receipts=ref([]),recs=ref([]),rec=ref(null),invoice=ref(null),tasks=ref([]),review=ref(null),notices=ref([]),dashboard=ref(null),monitor=ref(null),mappings=ref([]),policy=ref(null),busy=ref(false),error=ref(''),notice=ref(''),seedOpen=ref(false),shipOpen=ref(false),changeOpen=ref(false),receiveOpen=ref(false),selected=ref([]),attachment=ref(null),fileId=ref('')
const tracking=reactive({carrier:'',trackingNo:'',etaText:''})
const seed=reactive({supplierId:'',quantity:10,unitPrice:100,dueDate:new Date(Date.now()+7*86400000).toISOString().slice(0,10)}),shipment=reactive({asnNo:'',etaText:'',carrier:'',trackingNo:'',lines:[]}),proposal=reactive({reason:'',lines:[]}),receipt=reactive({receiptNo:'',finalReceipt:true,lines:[]}),opinion=ref(''),invoiceNo=ref(''),invoiceAmount=ref(''),caseComment=ref(''),recNo=ref(''),payAmount=ref(''),recSupplier=ref(''),tolerance=ref(3),policyReason=ref('')
const labels={WAIT_CONFIRM:'待供方确认',CONFIRMED:'已确认',CHANGE_PENDING:'ERP变更处理中',SHIPPING:'履约中',RECEIVED:'已收货',CANCELLED:'已取消',IN_TRANSIT:'在途',PARTIAL:'部分收货',NORMAL:'容差内',DIFFERENCE:'存在差异',WAITING_CONFIRMATION:'待双方确认',DISPUTED:'经理争议处理中',WITHDRAWN:'已撤回',REGISTERED:'发票已登记',AWAITING_RECEIPT:'已推送，待财务回执',ACCEPTED:'财务已受理',REJECTED:'已退回',PARTIALLY_PAID:'部分付款',PAID:'已付款',PENDING:'待处理',INFLIGHT:'发送中',DELIVERED:'接口已送达',APPLIED:'业务已入账',DUPLICATE:'重复事件已忽略',WAITING_VERSION:'等待前序版本',WAITING_DEPENDENCY:'等待关联单据',RETRY:'等待重试',FAILED:'失败，需排查',CONFLICT:'冲突，需来源纠正',APPROVED:'已批准',SUPERSEDED:'已被新版本替代',POSTED:'有效实收',REVERSED:'已冲销',RECON_DISPUTE:'对账争议',RECEIPT_REVERSAL:'人工实收冲销'}
const text=s=>labels[s]||s,mode=s=>s==='SANDBOX'?'本机沙箱':'真实接口',key=()=>crypto.randomUUID(),p=(path,body,method='GET',raw=false)=>props.api('/collaboration'+path,body,method,raw),post=(path,body={})=>p(path,body,'POST'),money=v=>v==='***'?'***':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){if(tab.value==='orders'){const d=await p('/orders?'+new URLSearchParams({current:page.value,size:20,searchKey:search.value}));rows.value=d.records;total.value=d.total}else if(tab.value==='receipts'){receipts.value=await p('/receipts');selected.value=[]}else if(tab.value==='settlements'){const d=await p('/reconciliations?current='+page.value+'&size=20');recs.value=d.records;total.value=d.total}else if(tab.value==='dashboard')dashboard.value=await p('/dashboard');else if(tab.value==='tasks')tasks.value=await p('/tasks');else if(tab.value==='notices')notices.value=await p('/notices');else if(tab.value==='integration')monitor.value=await props.api('/integration/monitor?current='+page.value+'&size=20')}
async function changeTab(t){tab.value=t;page.value=1;po.value=asn.value=rec.value=invoice.value=review.value=null;await load()}
async function inspect(id){po.value=await p('/orders/'+id);asn.value=null;shipOpen.value=changeOpen.value=false}
async function refresh(){await load();if(po.value)po.value=await p('/orders/'+po.value.id);if(asn.value)asn.value=await p('/asns/'+asn.value.id);if(rec.value)await openRec(rec.value.id);if(review.value)review.value=await p('/cases/'+review.value.id)}
async function prepareSeed(){mappings.value=await p('/mappings');seed.supplierId=mappings.value.find(m=>m.mode==='SANDBOX')?.supplierId||'';seedOpen.value=true}
async function createSeed(){await post('/sandbox/orders',{...seed,requestKey:key()});seedOpen.value=false;notice.value='沙箱ERP已排队生成订单，数秒后刷新订单列表。';await load()}
async function confirmPo(){po.value=await post('/orders/'+po.value.id+'/confirm',{rowVersion:po.value.rowVersion,comment:opinion.value||'已核对数量与交期'});notice.value='已确认当前来源版本'}
function prepareChange(){proposal.reason='';proposal.lines=po.value.lines.map(l=>({lineId:l.id,material:l.material,quantity:l.quantity,dueDate:l.dueDate}));changeOpen.value=true;shipOpen.value=false}
async function submitChange(){po.value=await post('/orders/'+po.value.id+'/change',{requestKey:key(),rowVersion:po.value.rowVersion,reason:proposal.reason,lines:proposal.lines.map(({lineId,quantity,dueDate})=>({lineId,quantity,dueDate}))});changeOpen.value=false}
function prepareShip(){Object.assign(shipment,{asnNo:'',etaText:'',carrier:'',trackingNo:'',lines:po.value.lines.map(l=>({poLineId:l.id,material:l.material,batchNo:'BATCH-'+new Date().toISOString().slice(0,10),quantity:Math.max(0,Number(l.quantity)-Number(l.shippedQuantity))}))});shipOpen.value=true;changeOpen.value=false}
async function shipGoods(){asn.value=await post('/orders/'+po.value.id+'/asns',{requestKey:key(),rowVersion:po.value.rowVersion,asnNo:shipment.asnNo||null,eta:shipment.etaText?new Date(shipment.etaText).getTime():null,carrier:shipment.carrier,trackingNo:shipment.trackingNo,lines:shipment.lines.filter(l=>l.quantity>0).map(({poLineId,batchNo,quantity})=>({poLineId,batchNo,quantity}))});shipOpen.value=false;po.value=await p('/orders/'+po.value.id);await openAsn(asn.value.id)}
async function openAsn(id){asn.value=await p('/asns/'+id);Object.assign(tracking,{carrier:asn.value.carrier||'',trackingNo:asn.value.trackingNo||'',etaText:asn.value.eta?new Date(Number(asn.value.eta)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''});receiveOpen.value=false}
async function saveTracking(){asn.value=await post('/asns/'+asn.value.id+'/tracking',{rowVersion:asn.value.rowVersion,carrier:tracking.carrier,trackingNo:tracking.trackingNo,eta:tracking.etaText?new Date(tracking.etaText).getTime():null})}
function prepareReceive(){receipt.receiptNo='';receipt.finalReceipt=true;receipt.lines=asn.value.lines.map(l=>({asnLineId:l.id,material:l.material,batchNo:l.batchNo,quantity:Math.max(0,Number(l.quantity)-Number(l.receivedQuantity))}));receiveOpen.value=true}
async function receiveGoods(){await post('/asns/'+asn.value.id+'/receive',{requestKey:key(),rowVersion:asn.value.rowVersion,receiptNo:receipt.receiptNo||null,receivedAt:0,finalReceipt:receipt.finalReceipt,lines:receipt.lines.filter(l=>l.quantity>0).map(({asnLineId,quantity})=>({asnLineId,quantity}))});receiveOpen.value=false;await refresh()}
async function demo(type,id,data={}){await post('/sandbox/commands',{requestKey:key(),type,businessId:id,data});notice.value='本机沙箱命令已排队，请数秒后刷新查看签名回执。'}
async function createRecon(){const picked=receipts.value.filter(l=>selected.value.includes(l.id));if(!picked.length)throw Error('请选择未占用的实收明细');rec.value=await post('/reconciliations',{requestKey:key(),supplierId:picked[0].supplierId,recNo:recNo.value||null,receiptLineIds:picked.map(l=>l.id)});tab.value='settlements';await load()}
async function openRec(id){rec.value=await p('/reconciliations/'+id);invoice.value=rec.value.invoiceId&&fin?await p('/invoices/'+rec.value.invoiceId):null;invoiceAmount.value=rec.value.amount;fileId.value='';attachment.value=null;opinion.value=''}
async function recAction(action){const body={rowVersion:rec.value.rowVersion,comment:opinion.value};if(action==='confirm'){body.comment=body.comment||'已核对实收、数量及金额'}else if(!body.comment.trim())throw Error('请填写处理意见');const d=await post('/reconciliations/'+rec.value.id+'/'+action,body);if(action==='dispute'){review.value=d;await openRec(rec.value.id)}else if(action==='withdraw'){rec.value=null;await load()}else{rec.value=d;if(rec.value.invoiceId&&fin)invoice.value=await p('/invoices/'+rec.value.invoiceId)}}
async function upload(){if(!attachment.value)throw Error('请选择发票 PDF/PNG/JPEG');const data=new FormData();data.append('file',attachment.value);const f=await p('/reconciliations/'+rec.value.id+'/files',data,'POST');fileId.value=f.id;notice.value='发票附件已私有保存'}
async function registerInvoice(){invoice.value=await post('/reconciliations/'+rec.value.id+'/invoices',{requestKey:key(),rowVersion:rec.value.rowVersion,invoiceNo:invoiceNo.value,amount:Number(invoiceAmount.value),fileId:fileId.value});rec.value=await p('/reconciliations/'+rec.value.id)}
async function reviseInvoice(){invoice.value=await post('/invoices/'+invoice.value.id+'/revise',{rowVersion:invoice.value.rowVersion,fileId:fileId.value,reason:opinion.value})}
async function paymentRequest(){invoice.value=await post('/invoices/'+invoice.value.id+'/payment-request',{rowVersion:invoice.value.rowVersion})}
async function pushInvoice(){invoice.value=await post('/invoices/'+invoice.value.id+'/push',{rowVersion:invoice.value.rowVersion})}
async function download(id){const b=await p('/files/'+id,undefined,'GET',true),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='invoice-'+id;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function inspectCase(id){review.value=await p('/cases/'+id);caseComment.value=''}
async function decide(t,action){review.value=await post('/cases/'+review.value.id+'/tasks/'+t.id,{action,comment:caseComment.value});await load()}
async function retry(kind,id){await props.api('/integration/'+kind+'/'+id+'/retry',{},'POST');await load()}
async function readPolicy(){policy.value=await p('/policy');tolerance.value=policy.value.tolerancePct}
async function savePolicy(){policy.value=await post('/policy',{expectedVersion:policy.value.version,tolerancePct:tolerance.value,reason:policyReason.value});notice.value='新容差仅用于后续发运，已有ASN继续使用创建时版本'}
onMounted(()=>run(load))
</script>
<template><section class="col-panel" :aria-busy="busy">
<div class="panel-heading"><div><h2>采购协同</h2><p>订单确认 → 发运 → 实收 → 双方对账 → 发票及财务回执</p></div><button class="btn" :disabled="busy" @click="run(refresh)">刷新协同</button></div>
<div class="col-tabs"><button v-for="t in [{id:'orders',name:'采购订单'},{id:'dashboard',name:'交付看板'},...(buyer?[{id:'receipts',name:'实收与建账'}]:[]),{id:'settlements',name:'对账与发票'},...(buyer?[{id:'tasks',name:'经理待办'}]:[]),{id:'notices',name:'协同通知'},...(admin?[{id:'integration',name:'集成监控'}]:[])]" :key="t.id" :class="['btn',{primary:tab===t.id}]" :disabled="busy" @click="run(()=>changeTab(t.id))">{{t.name}}</button></div>
<p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="info-note" role="status">{{notice}}</p>
<template v-if="tab==='orders'"><form class="table-toolbar" @submit.prevent="page=1;run(load)"><input aria-label="搜索采购订单" v-model="search" placeholder="订单号或供应商"/><button class="btn" :disabled="busy">查询</button><button v-if="buyer" type="button" class="btn" :disabled="busy" @click="run(prepareSeed)">生成本机沙箱订单</button><button v-if="buyer" type="button" class="btn" :disabled="busy" @click="run(readPolicy)">收货容差设置</button></form>
<form v-if="seedOpen" class="col-card" @submit.prevent="run(createSeed)"><h3>本机沙箱 ERP 生成测试订单</h3><p class="info-note">本操作只创建沙箱订单，不向真实 ERP 下单。订单经签名回写后出现在列表。</p><div class="col-grid"><label>映射供应商<select v-model="seed.supplierId" required><option value="">请选择</option><option v-for="m in mappings.filter(m=>m.mode==='SANDBOX')" :key="m.externalKey" :value="m.supplierId">{{m.supplierName}}</option></select></label><label>数量<input type="number" min="0.001" step="0.001" v-model.number="seed.quantity" required/></label><label>单价<input type="number" min="0.0001" step="0.0001" v-model.number="seed.unitPrice" required/></label><label>交期<input type="date" v-model="seed.dueDate" required/></label></div><button class="btn primary" :disabled="busy">生成沙箱订单</button><button type="button" class="btn" @click="seedOpen=false">关闭</button></form>
<form v-if="policy" class="col-card" @submit.prevent="run(savePolicy)"><h3>收货容差 · 版本 {{policy.version}}</h3><label>容差百分比<input type="number" min="0" max="100" step="0.001" v-model.number="tolerance" required/></label><label>调整依据<input v-model="policyReason" required maxlength="500"/></label><button class="btn" :disabled="busy">发布新版本</button><button type="button" class="btn" @click="policy=null">关闭</button></form>
<div class="table-scroll"><table><thead><tr><th>订单</th><th>供应商</th><th>来源</th><th>状态</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.poNo}}</td><td>{{r.supplierName}}</td><td><b class="mode">{{mode(r.mode)}}</b></td><td>{{text(r.status)}}</td><td>{{r.sourceVersion}}</td><td><button class="text-btn" :disabled="busy" @click="run(()=>inspect(r.id))">查看订单</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty-state">当前范围暂无订单。内部采购可生成本机沙箱测试订单。</p>
</template>
<article v-if="po&&tab==='orders'" class="col-card"><div class="panel-heading"><h3>{{po.poNo}} · {{text(po.status)}}</h3><button class="btn" @click="po=asn=null">关闭订单</button></div><p><b class="mode">{{mode(po.mode)}}</b> · {{po.currency}} · 来源版本 {{po.sourceVersion}} · 已确认版本 {{po.confirmedVersion}} · 金额 {{money(po.amount)}}</p><div class="table-scroll"><table><thead><tr><th>物料</th><th>订单量</th><th>交期</th><th>单价</th><th>已发</th><th>实收</th></tr></thead><tbody><tr v-for="l in po.lines" :key="l.id"><td>{{l.material}}</td><td>{{l.quantity}}</td><td>{{l.dueDate}}</td><td>{{l.unitPrice===undefined?'权限受限':money(l.unitPrice)}}</td><td>{{l.shippedQuantity}}</td><td>{{l.receivedQuantity}}</td></tr></tbody></table></div>
<div v-if="ship" class="col-actions"><button class="btn primary" :disabled="busy||!['WAIT_CONFIRM','CONFIRMED','SHIPPING'].includes(po.status)" @click="run(confirmPo)">确认当前订单</button><button class="btn" :disabled="busy||['CANCELLED','RECEIVED','CHANGE_PENDING'].includes(po.status)" @click="prepareChange">建议交期／数量变更</button><button class="btn" :disabled="busy||!['CONFIRMED','SHIPPING'].includes(po.status)" @click="prepareShip">填写发运通知</button></div>
<form v-if="changeOpen" class="col-card" @submit.prevent="run(submitChange)"><h4>供应商变更建议（等待 ERP 正式回写后生效）</h4><div v-for="l in proposal.lines" :key="l.lineId" class="col-grid"><span>{{l.material}}</span><label>建议数量<input type="number" min="0.001" step="0.001" v-model.number="l.quantity" required/></label><label>建议交期<input type="date" v-model="l.dueDate" required/></label></div><label>变更原因<textarea v-model="proposal.reason" required maxlength="1000"/></label><button class="btn primary" :disabled="busy">提交变更建议</button></form>
<form v-if="shipOpen" class="col-card" @submit.prevent="run(shipGoods)"><h4>发运通知（可分批次）</h4><div class="col-grid"><label>ASN编号（可留空）<input v-model="shipment.asnNo"/></label><label>预计到货<input type="datetime-local" v-model="shipment.etaText"/></label><label>承运商<input v-model="shipment.carrier"/></label><label>运单号<input v-model="shipment.trackingNo"/></label></div><div v-for="(l,i) in shipment.lines" :key="i" class="col-grid"><span>{{l.material}}</span><label>批次<input v-model="l.batchNo" required/></label><label>发运量（0不发）<input type="number" min="0" step="0.001" v-model.number="l.quantity" required/></label><button class="btn" type="button" @click="shipment.lines.push({...l,quantity:0,batchNo:''})">增加批次</button></div><button class="btn primary" :disabled="busy">提交发运通知</button></form>
<div v-if="po.changes.length"><h4>变更记录</h4><p v-for="c in po.changes" :key="c.id">{{text(c.status)}} · 基于版本 {{c.baseVersion}} · {{c.proposal.reason}}</p><div v-if="buyer&&po.mode==='SANDBOX'&&po.status==='CHANGE_PENDING'" class="col-actions"><button class="btn" :disabled="busy" @click="run(()=>demo('PO_CHANGE',po.id,{poNo:po.poNo,action:'APPROVE'}))">沙箱 ERP 接受建议</button><button class="btn" :disabled="busy" @click="run(()=>demo('PO_CHANGE',po.id,{poNo:po.poNo,action:'REJECT'}))">沙箱 ERP 拒绝建议</button></div></div>
<h4>发运通知</h4><p v-if="!po.asns.length">尚未发运</p><div v-for="a in po.asns" :key="a.id" class="col-actions"><span>{{a.asnNo}} · {{text(a.status)}} · {{text(a.diffFlag)}}</span><button class="text-btn" :disabled="busy" @click="run(()=>openAsn(a.id))">查看发运／收货</button></div><p v-for="m in po.mes" :key="m.sourceRef">MES优先级 {{m.priority}} · {{m.sourceRef}} · {{mode(m.mode)}}</p><button v-if="buyer&&po.mode==='SANDBOX'" class="btn" :disabled="busy" @click="run(()=>demo('MES_PRIORITY',po.id,{poNo:po.poNo,priority:80}))">模拟 MES 紧急优先级</button>
</article>
<article v-if="asn&&tab==='orders'" class="col-card"><h3>{{asn.asnNo}} · {{text(asn.status)}} · {{text(asn.diffFlag)}}</h3><p>容差 {{asn.tolerancePct}}%（创建时版本 {{asn.policyVersion}}） · 承运商 {{asn.carrier||'未填'}} · 运单 {{asn.trackingNo||'未填'}}</p><div class="table-scroll"><table><thead><tr><th>物料</th><th>批次</th><th>发运量</th><th>累计实收</th></tr></thead><tbody><tr v-for="l in asn.lines" :key="l.id"><td>{{l.material}}</td><td>{{l.batchNo}}</td><td>{{l.quantity}}</td><td>{{l.receivedQuantity}}</td></tr></tbody></table></div><form v-if="ship&&asn.status!=='RECEIVED'" class="col-card" @submit.prevent="run(saveTracking)"><h4>更新物流</h4><div class="col-grid"><label>承运商<input v-model="tracking.carrier" maxlength="80"/></label><label>运单号<input v-model="tracking.trackingNo" maxlength="96"/></label><label>预计到货<input type="datetime-local" v-model="tracking.etaText"/></label></div><button class="btn" :disabled="busy">保存物流信息</button></form><div v-if="buyer&&asn.status!=='RECEIVED'" class="col-actions"><button class="btn primary" :disabled="busy" @click="prepareReceive">登记人工实收</button><button v-if="po.mode==='SANDBOX'" class="btn" :disabled="busy" @click="run(()=>demo('RECEIPT',asn.id,{finalReceipt:true}))">模拟 ERP 全量实收</button></div><form v-if="receiveOpen" @submit.prevent="run(receiveGoods)"><label>收货编号（可留空）<input v-model="receipt.receiptNo"/></label><div v-for="l in receipt.lines" :key="l.asnLineId" class="col-grid"><span>{{l.material}}／{{l.batchNo}}</span><label>本次实收量<input type="number" min="0" step="0.001" v-model.number="l.quantity"/></label></div><label><input type="checkbox" v-model="receipt.finalReceipt"/>本次为最终收货，按累计实收计算短缺容差</label><button class="btn primary" :disabled="busy">保存实收记录</button></form><h4>收货历史</h4><p v-for="r in asn.receipts" :key="r.id">{{r.receiptNo}} · {{text(r.status)}} · {{r.finalReceipt?'最终':'分次'}}收货</p></article>
<template v-if="tab==='receipts'"><p class="info-note">选择同一供应商、币种和来源模式的未占用实收明细生成对账单；单价使用收货时快照。</p><div class="table-scroll"><table><thead><tr><th>选择</th><th>供应商</th><th>订单／收货</th><th>物料／批次</th><th>数量</th><th>金额</th><th>来源／占用</th><th>纠错</th></tr></thead><tbody><tr v-for="r in receipts" :key="r.id"><td><input type="checkbox" :disabled="!!r.allocatedReconciliation" v-model="selected" :value="r.id"/></td><td>{{r.supplierName}}</td><td>{{r.poNo}}<small>{{r.receiptNo}}</small></td><td>{{r.material}}／{{r.batchNo}}</td><td>{{r.quantity}}</td><td>{{money(r.amount)}} {{r.currency}}</td><td>{{mode(r.mode)}} · {{r.allocatedReconciliation?'已占用':'可建账'}}</td><td><button class="text-btn" :disabled="busy||!!r.allocatedReconciliation" @click="run(async()=>{if(!opinion.trim())throw Error('请填写下方冲销依据');review=await post('/receipts/'+r.receiptId+'/reversal',{rowVersion:0,comment:opinion})})">申请冲销</button></td></tr></tbody></table></div><div class="col-actions"><input v-model="recNo" placeholder="对账编号（可留空）"/><button class="btn primary" :disabled="busy||!selected.length" @click="run(createRecon)">用选中实收生成对账单</button></div><label>实收冲销依据<textarea v-model="opinion" maxlength="2000" placeholder="只有未对账的人工实收可申请；经理审批通过后冲销"/></label></template>
<template v-if="tab==='settlements'"><div class="table-scroll"><table><thead><tr><th>对账单</th><th>供应商</th><th>来源</th><th>金额</th><th>双方确认</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in recs" :key="r.id"><td>{{r.recNo}}</td><td>{{r.supplierName}}</td><td>{{mode(r.mode)}}</td><td>{{money(r.amount)}} {{r.currency}}</td><td>采购{{r.buyerConfirmed?'✓':'待确认'}}／供方{{r.supplierConfirmed?'✓':'待确认'}}</td><td>{{text(r.status)}}</td><td><button class="text-btn" :disabled="busy" @click="run(()=>openRec(r.id))">查看对账与发票</button></td></tr></tbody></table></div><p v-if="!recs.length" class="empty-state">尚无对账单，内部采购先在“实收与建账”生成。</p></template>
<article v-if="rec&&tab==='settlements'" class="col-card"><h3>{{rec.recNo}} · {{text(rec.status)}}</h3><p><b class="mode">{{mode(rec.mode)}}</b> · 数量 {{rec.quantity}} · 金额 {{money(rec.amount)}} {{rec.currency}} · 采购{{rec.buyerConfirmed?'已确认':'待确认'}}／供方{{rec.supplierConfirmed?'已确认':'待确认'}}</p><div class="table-scroll"><table><thead><tr><th>订单／物料</th><th>数量</th><th>单价</th><th>金额</th></tr></thead><tbody><tr v-for="l in rec.lines" :key="l.id||l.receiptLineId"><td>{{l.poNo}}／{{l.material}}</td><td>{{l.quantity}}</td><td>{{l.unitPrice===undefined?'权限受限':money(l.unitPrice)}}</td><td>{{money(l.amount)}}</td></tr></tbody></table></div><label>处理意见／差异依据<textarea v-model="opinion" maxlength="2000"/></label><div class="col-actions"><button class="btn primary" :disabled="busy||rec.status!=='WAITING_CONFIRMATION'" @click="run(()=>recAction('confirm'))">{{portal?'供应商确认':'采购确认'}}</button><button class="btn" :disabled="busy||rec.status==='WITHDRAWN'" @click="run(()=>recAction('difference'))">提出差异</button><button class="btn" :disabled="busy||rec.status==='WITHDRAWN'" @click="run(()=>recAction('discuss'))">提交讨论</button><button v-if="buyer" class="btn" :disabled="busy||!['DIFFERENCE','DISPUTED'].includes(rec.status)" @click="run(()=>recAction('resolve'))">提出解决意见，重新双确认</button><button class="btn" :disabled="busy||!['DIFFERENCE','DISPUTED'].includes(rec.status)" @click="run(()=>recAction('dispute'))">升级经理处理</button><button v-if="buyer" class="btn" :disabled="busy||rec.buyerConfirmed||rec.supplierConfirmed||!!rec.invoiceId||rec.status==='WITHDRAWN'" @click="run(()=>recAction('withdraw'))">撤回未确认账单</button></div>
<h4>讨论与确认记录</h4><p v-for="h in rec.history" :key="h.id">{{h.portal?'供应商':'内部'}} · {{h.action}} · {{h.content?.comment}}</p><div v-for="c in rec.cases" :key="c.id" class="col-actions"><span>经理处理 · {{text(c.status)}}</span><button class="text-btn" :disabled="busy" @click="run(()=>inspectCase(c.id))">查看处理依据</button></div>
<div v-if="fin&&rec.status==='CONFIRMED'" class="col-card"><h4>发票附件与登记</h4><p>金额须与已确认账单一致。附件仅双方财务及授权共享渠道可读取。</p><label>发票附件<input type="file" accept="application/pdf,image/png,image/jpeg" @change="attachment=$event.target.files[0]"/></label><button class="btn" :disabled="busy||!attachment" @click="run(upload)">上传私有附件</button><span v-if="fileId"> 已上传</span><form v-if="!invoice" @submit.prevent="run(registerInvoice)"><div class="col-grid"><label>发票号码<input v-model="invoiceNo" required maxlength="64"/></label><label>发票金额<input type="number" min="0.01" step="0.01" v-model="invoiceAmount" required/></label></div><button class="btn primary" :disabled="busy||!fileId">登记发票</button></form><button v-if="invoice?.status==='REJECTED'" class="btn" :disabled="busy||!fileId||!opinion.trim()" @click="run(reviseInvoice)">按处理意见换件重提</button></div>
</article>
<article v-if="invoice&&rec&&tab==='settlements'" class="col-card"><h3>发票 {{invoice.invoiceNo}} · {{text(invoice.status)}}</h3><p>{{money(invoice.amount)}} {{invoice.currency}} · 附件版本 {{invoice.revision}} · 累计付款 {{money(invoice.paidAmount)}}</p><p>接口传输：{{text(invoice.delivery.status)||'尚未推送'}} · 尝试 {{invoice.delivery.attempts||0}} 次。财务受理与付款以签名业务回执为准。</p><div class="col-actions"><button class="btn" :disabled="busy" @click="run(()=>download(invoice.fileId))">下载本版附件</button><button v-if="fin&&!portal" class="btn primary" :disabled="busy||invoice.status!=='REGISTERED'" @click="run(pushInvoice)">推送共享财务</button></div><div v-if="fin&&!portal&&['ACCEPTED','PARTIALLY_PAID'].includes(invoice.status)" class="col-actions"><button class="btn" :disabled="busy||!!invoice.paymentApplication?.id" @click="run(paymentRequest)">提交付款申请</button><span>付款申请：{{text(invoice.paymentApplication?.status)||'尚未申请'}}。实际付款以签名付款回执为准。</span></div><h4>财务回执</h4><p v-for="(a,i) in invoice.acknowledgements" :key="i">版本 {{a.revision}} · {{text(a.result)}} · {{a.remoteRef}} · {{a.applied?'已应用':'保留历史'}}</p><div v-if="fin&&!portal&&invoice.mode==='SANDBOX'&&['ACCEPTED','PARTIALLY_PAID'].includes(invoice.status)" class="col-actions"><label>模拟付款金额<input type="number" min="0.01" step="0.01" v-model="payAmount"/></label><button class="btn" :disabled="busy||!(Number(payAmount)>0)" @click="run(()=>demo('PAYMENT',invoice.id,{amount:Number(payAmount)}))">本机沙箱模拟付款回执</button></div><details><summary>附件版本历史</summary><p v-for="r in invoice.revisions" :key="r.revision">版本 {{r.revision}} <button class="text-btn" :disabled="busy" @click="run(()=>download(r.fileId))">下载</button></p></details></article>
<template v-if="tab==='dashboard'&&dashboard"><div class="col-grid"><p>在途数量 <b>{{dashboard.inTransit}}</b></p><p>累计实收 <b>{{dashboard.received}}</b></p><p>逾期未收 <b>{{dashboard.overdue}}</b></p></div><p v-if="dashboard.truncated" class="info-note">仅展示最近1000张订单，请按订单查询进一步核对。</p><div class="table-scroll"><table><thead><tr><th>订单</th><th>供应商</th><th>来源</th><th>在途</th><th>实收</th><th>逾期</th><th>MES优先级</th></tr></thead><tbody><tr v-for="r in dashboard.rows" :key="r.poId"><td>{{r.poNo}}</td><td>{{r.supplierName}}</td><td>{{mode(r.mode)}}</td><td>{{r.inTransit}}</td><td>{{r.received}}</td><td>{{r.overdue}}</td><td>{{r.priorities.map(p=>p.priority).join(' / ')||'未接收'}}</td></tr></tbody></table></div><p>逾期／超容差事件保留评估依据，风险等级联动在后续风险阶段接入。</p></template>
<template v-if="tab==='tasks'"><p v-if="!tasks.length" class="empty-state">暂无可由当前用户处理的经理任务。申请人不能审批本人申请。</p><div v-for="t in tasks" :key="t.id" class="col-actions"><span>{{text(t.kind)}} · {{t.name}}</span><button class="btn" :disabled="busy" @click="run(()=>inspectCase(t.caseId))">查看依据并处理</button></div></template>
<article v-if="review" class="col-card"><h3>{{text(review.kind)}} · {{text(review.status)}}</h3><p>申请依据：{{review.reason}}</p><p v-if="review.kind==='RECON_DISPUTE'">对账单 {{review.basis.recNo}} · 金额 {{money(review.basis.amount)}} {{review.basis.currency}}。批准后双方必须重新确认。</p><template v-else><p>人工实收 {{review.basis.receiptNo}} · {{review.basis.lines.length}} 行。批准后保留冲销历史并重新计算履约。</p><p v-for="l in review.basis.lines" :key="l.ID">数量 {{l.QUANTITY}}</p></template><p v-if="review.reviewComment">经理意见：{{review.reviewComment}}</p><template v-if="!portal&&review.status==='PENDING'"><label>经理意见<textarea v-model="caseComment" maxlength="1000"/></label><div v-for="t in review.tasks" :key="t.id" class="col-actions"><button class="btn primary" :disabled="busy||!caseComment.trim()" @click="run(()=>decide(t,'APPROVE'))">批准处理</button><button class="btn" :disabled="busy||!caseComment.trim()" @click="run(()=>decide(t,'REJECT'))">退回</button></div></template><button v-if="review.status==='PENDING'" class="btn" :disabled="busy" @click="run(async()=>{await post('/cases/'+review.id+'/withdraw');review=await p('/cases/'+review.id);await load()})">撤回本人申请</button><button class="btn" @click="review=null">关闭处理详情</button></article>
<template v-if="tab==='notices'"><p v-if="!notices.length" class="empty-state">暂无协同通知</p><article v-for="n in notices" :key="n.id" class="col-card"><strong>{{n.message}}</strong><small>{{n.createdAt}} · {{n.businessId}}</small></article></template>
<template v-if="tab==='integration'&&monitor"><p class="info-note">本机 ERP／MES／财务沙箱仅用于本地验证。实际外部系统联调尚未完成。失败可重试原事件，冲突应由来源系统纠正。</p><h3>出站记录（{{monitor.outboxTotal}}）</h3><div class="table-scroll"><table><thead><tr><th>事件／业务</th><th>状态</th><th>尝试</th><th>错误代码</th><th>操作</th></tr></thead><tbody><tr v-for="r in monitor.outbox" :key="r.id"><td>{{r.type}}<small>{{r.businessId}} · 版本 {{r.version}}</small></td><td>{{text(r.status)}}</td><td>{{r.attempts}}</td><td>{{r.lastError}}</td><td><button class="text-btn" :disabled="busy||!['FAILED','RETRY'].includes(r.status)" @click="run(()=>retry('outbox',r.id))">重试原事件</button></td></tr></tbody></table></div><h3>入站记录（{{monitor.inboxTotal}}）</h3><div class="table-scroll"><table><thead><tr><th>资源／业务</th><th>状态</th><th>尝试</th><th>错误代码</th><th>操作</th></tr></thead><tbody><tr v-for="r in monitor.inbox" :key="r.id"><td>{{r.resource}}<small>{{r.businessKey}} · 版本 {{r.version}}</small></td><td>{{text(r.status)}}</td><td>{{r.attempts}}</td><td>{{r.lastError}}</td><td><button class="text-btn" :disabled="busy||!['FAILED','RETRY','WAITING_DEPENDENCY','WAITING_VERSION'].includes(r.status)" @click="run(()=>retry('inbox',r.id))">重试原事件</button></td></tr></tbody></table></div></template>
<div v-if="['orders','settlements','integration'].includes(tab)" class="table-footer"><span v-if="tab!=='integration'">共 {{total}} 条</span><button class="btn" :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><span>{{page}}</span><button class="btn" :disabled="busy||(tab==='integration'?page*20>=Math.max(monitor?.inboxTotal||0,monitor?.outboxTotal||0):page*20>=total)" @click="page++;run(load)">下一页</button></div>
</section></template>
<style scoped>.col-panel{padding:20px}.col-tabs,.col-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:16px 0}.col-card{border:1px solid #dce5e0;border-radius:10px;padding:20px;margin:20px 0;background:#fff}.col-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:14px 0}.col-panel label{display:flex;flex-direction:column;gap:6px;margin:10px 0}.col-panel input[type=checkbox]{width:auto}.col-panel small{display:block;color:#66766d;font-size:12px}.col-panel .mode{color:#6c4e15;background:#fff4d8;border-radius:5px;padding:4px 7px;font-size:12px}.col-panel td{vertical-align:middle}.col-panel textarea{min-height:70px;width:100%}.col-panel .col-card h3{margin:0 0 12px}.col-panel .table-scroll{overflow-x:auto}</style>
